<?php use App\Core\CSRF;$edit=!empty($court);$days=[1=>'Segunda',2=>'Terça',3=>'Quarta',4=>'Quinta',5=>'Sexta',6=>'Sábado',7=>'Domingo'];?>
<div class="sports-head"><div><h1><?=$edit?'Editar quadra':'Nova quadra'?></h1><p>Estrutura, funcionamento, preços e indisponibilidades.</p></div><a class="btn btn-outline-secondary" href="/sports/courts">Voltar</a></div>
<form class="card border-0 shadow-sm mb-4" method="post" action="<?=$edit?'/sports/courts/'.(int)$court['id'].'/update':'/sports/courts'?>"><div class="card-body"><?=CSRF::field()?><div class="row g-3"><div class="col-md-6"><label class="form-label">Nome *</label><input class="form-control" name="name" required value="<?=htmlspecialchars($court['name']??'')?>"></div><div class="col-md-6"><label class="form-label">Unidade</label><select class="form-select" name="unit_id"><option value="">Sem unidade</option><?php foreach($units as $u):?><option value="<?=(int)$u['id']?>" <?=($court['unit_id']??null)==$u['id']?'selected':''?>><?=htmlspecialchars($u['name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Tipo de piso</label><input class="form-control" name="surface" value="<?=htmlspecialchars($court['surface']??'')?>" placeholder="Sintético, saibro..."></div><div class="col-md-4"><label class="form-label">Capacidade</label><input class="form-control" type="number" name="capacity" value="<?=htmlspecialchars($court['capacity']??'')?>"></div><div class="col-md-4"><label class="form-label">URL da foto</label><input class="form-control" name="photo_path" value="<?=htmlspecialchars($court['photo_path']??'')?>"></div><div class="col-12"><label class="form-label">Descrição</label><textarea class="form-control" name="description" rows="3"><?=htmlspecialchars($court['description']??'')?></textarea></div><div class="col-md-4"><label class="form-label">Duração mínima (min)</label><input class="form-control" type="number" name="minimum_minutes" value="<?=(int)($court['minimum_minutes']??60)?>"></div><div class="col-md-4"><label class="form-label">Duração máxima (min)</label><input class="form-control" type="number" name="maximum_minutes" value="<?=(int)($court['maximum_minutes']??180)?>"></div><div class="col-md-4"><label class="form-label">Intervalo de limpeza (min)</label><input class="form-control" type="number" name="interval_minutes" value="<?=(int)($court['interval_minutes']??0)?>"></div><div class="col-12"><label class="form-label d-block">Modalidades *</label><?php foreach($modalities as $m):?><label class="sports-check"><input type="checkbox" name="modalities[]" value="<?=(int)$m['id']?>" <?=in_array((int)$m['id'],$enabledModalities,true)?'checked':''?>><?=htmlspecialchars($m['name'])?></label><?php endforeach;?><?php if(!$modalities):?><a href="/sports/settings">Cadastre uma modalidade primeiro.</a><?php endif;?></div><div class="col-12 d-flex gap-4"><label class="form-check"><input class="form-check-input" type="checkbox" name="indoor" <?=$edit&&$court['indoor']?'checked':''?>> Coberta</label><label class="form-check"><input class="form-check-input" type="checkbox" name="lighting" <?=$edit&&$court['lighting']?'checked':''?>> Iluminação</label><label class="form-check"><input class="form-check-input" type="checkbox" name="active" <?=!$edit||$court['active']?'checked':''?>> Ativa</label></div></div><button class="btn btn-primary mt-4">Salvar quadra</button></div></form>
<?php if($edit):?><div class="row g-4"><div class="col-xl-6"><form class="card border-0 shadow-sm" method="post" action="/sports/courts/<?=(int)$court['id']?>/hours"><div class="card-body"><?=CSRF::field()?><h2 class="h5">Horários de funcionamento</h2><?php foreach($days as $n=>$day):$h=$hours[$n]??null;?><div class="sports-hour-row"><strong><?=$day?></strong><input type="time" class="form-control" name="start[<?=$n?>]" value="<?=$h?substr($h['start_time'],0,5):''?>"><span>até</span><input type="time" class="form-control" name="end[<?=$n?>]" value="<?=$h?substr($h['end_time'],0,5):''?>"></div><?php endforeach;?><button class="btn btn-primary mt-3">Salvar horários</button></div></form></div><div class="col-xl-6"><div class="card border-0 shadow-sm mb-4"><div class="card-body"><h2 class="h5">Preços por horário</h2><p class="small text-secondary">Combine modalidade, dia, faixa de horário, duração, feriado/data específica ou período especial.</p><form method="post" action="/sports/courts/<?=(int)$court['id']?>/prices" class="row g-2"><?=CSRF::field()?><div class="col-md-6"><select class="form-select" name="modality_id"><option value="">Todas as modalidades</option><?php foreach($modalities as $m):?><option value="<?=(int)$m['id']?>"><?=htmlspecialchars($m['name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><select class="form-select" name="weekday"><option value="">Todos os dias</option><?php foreach($days as $n=>$day):?><option value="<?=$n?>"><?=$day?></option><?php endforeach;?></select></div><div class="col-4"><input class="form-control" type="time" name="start_time" aria-label="Início"></div><div class="col-4"><input class="form-control" type="time" name="end_time" aria-label="Fim"></div><div class="col-4"><input class="form-control" name="price_per_hour" required placeholder="R$ / hora"></div><div class="col-md-4"><select class="form-select" name="rule_type"><option value="standard">Regra normal</option><option value="holiday">Feriado/data</option><option value="special">Período especial</option></select></div><div class="col-md-4"><input class="form-control" type="date" name="specific_date" title="Data específica"></div><div class="col-md-4"><input class="form-control" name="label" maxlength="160" placeholder="Nome: feriado/evento"></div><div class="col-md-6"><div class="input-group"><span class="input-group-text">De</span><input class="form-control" type="date" name="valid_from"><span class="input-group-text">até</span><input class="form-control" type="date" name="valid_to"></div></div><div class="col-md-6"><div class="input-group"><input class="form-control" type="number" name="minimum_duration_minutes" min="15" step="15" placeholder="Duração mín."><input class="form-control" type="number" name="maximum_duration_minutes" min="15" step="15" placeholder="Duração máx."></div></div><div class="col-12"><button class="btn btn-outline-primary w-100">Adicionar regra</button></div></form><?php foreach($prices as $p):$ruleLabel=['holiday'=>'Feriado/data','special'=>'Período especial','standard'=>'Normal'][$p['rule_type']??'standard']??'Normal';?><div class="sports-list-row"><span><strong>R$ <?=number_format((float)$p['price_per_hour'],2,',','.')?>/h</strong><small><?=htmlspecialchars($p['modality_name']??'Todas')?> · <?=$p['weekday']?$days[$p['weekday']]:'Todos os dias'?> · <?=$p['start_time']?substr($p['start_time'],0,5).'–'.substr($p['end_time'],0,5):'Qualquer horário'?> · <?=$ruleLabel?><?php if(!empty($p['specific_date'])):?> · <?=date('d/m/Y',strtotime($p['specific_date']))?><?php endif;?><?php if(!empty($p['valid_from'])||!empty($p['valid_to'])):?> · período <?=!empty($p['valid_from'])?date('d/m/Y',strtotime($p['valid_from'])):'…'?>–<?=!empty($p['valid_to'])?date('d/m/Y',strtotime($p['valid_to'])):'…'?><?php endif;?><?php if(!empty($p['minimum_duration_minutes'])||!empty($p['maximum_duration_minutes'])):?> · duração <?=$p['minimum_duration_minutes']?:'…'?>–<?=$p['maximum_duration_minutes']?:'…'?> min<?php endif;?><?php if(!empty($p['rule_label'])):?> · <?=htmlspecialchars($p['rule_label'])?><?php endif;?></small></span><form method="post" action="/sports/prices/<?=(int)$p['id']?>/delete"><?=CSRF::field()?><button class="btn btn-sm btn-outline-danger">Excluir</button></form></div><?php endforeach;?></div></div><div class="card border-0 shadow-sm"><div class="card-body"><h2 class="h5">Bloquear período</h2><form method="post" action="/sports/blocks" class="row g-2"><?=CSRF::field()?><input type="hidden" name="court_id" value="<?=(int)$court['id']?>"><div class="col-6"><input class="form-control" type="datetime-local" name="starts_at" required></div><div class="col-6"><input class="form-control" type="datetime-local" name="ends_at" required></div><div class="col-12"><input class="form-control" name="reason" placeholder="Manutenção, evento..."></div><div class="col-12"><button class="btn btn-outline-primary w-100">Bloquear</button></div></form><?php foreach($blocks as $b):?><div class="sports-list-row"><span><strong><?=date('d/m H:i',strtotime($b['starts_at']))?>–<?=date('d/m H:i',strtotime($b['ends_at']))?></strong><small><?=htmlspecialchars($b['reason']??'Indisponível')?></small></span><form method="post" action="/sports/blocks/<?=(int)$b['id']?>/cancel"><?=CSRF::field()?><button class="btn btn-sm btn-outline-danger">Cancelar</button></form></div><?php endforeach;?></div></div></div></div><?php endif;?>
